function hydrate(){document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
function pageHead(title,sub,actions='',eyebrow=''){return `<div class="page-head"><div>${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1>${title}</h1><p>${sub}</p></div><div class="row">${actions}</div></div>`}
function stat(label,value,change,ic,i=0){return `<article class="stat card"><div class="label">${label}<span class="stat-icon">${icon(ic)}</span></div><div class="number">${value}</div><div class="change"><strong>↗ ${change}</strong><span>较上个周期</span></div><svg class="sparkline" viewBox="0 0 80 28"><path d="M0 24 8 20 17 23 26 14 34 17 44 9 53 12 63 6 72 8 80 2" fill="none" stroke="currentColor" stroke-width="1.5"/></svg></article>`}
function chart(period=state.chartPeriod){let monthly=period==='近 30 天'||period==='上月';return `<div class="chart"><svg viewBox="0 0 650 180" preserveAspectRatio="none"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#b29bdc" stop-opacity=".22"/><stop offset="1" stop-color="#b29bdc" stop-opacity="0"/></linearGradient></defs>${[20,60,100,140].map((y,i)=>`<path class="grid" d="M37 ${y}H640"/><text x="0" y="${y+3}">${[12,9,6,3][i]}k</text>`).join('')}<path d="M38 127 C80 125 84 80 135 85 S195 130 236 104 S303 48 335 63 S392 102 435 72 S494 37 536 49 S599 91 639 54" fill="none" stroke="#dfd8ee" stroke-dasharray="5 5" stroke-width="2"/><path d="${monthly?'M38 134 C82 120 89 114 135 102 S190 42 236 64 S290 98 335 57 S390 57 435 38 S505 80 536 48 S597 28 639 15':'M38 120 C80 119 88 78 135 84 S195 110 236 72 S290 98 335 47 S391 40 435 59 S492 37 536 39 S596 63 639 17'} L639 166 H38Z" fill="url(#area)"/><path d="${monthly?'M38 134 C82 120 89 114 135 102 S190 42 236 64 S290 98 335 57 S390 57 435 38 S505 80 536 48 S597 28 639 15':'M38 120 C80 119 88 78 135 84 S195 110 236 72 S290 98 335 47 S391 40 435 59 S492 37 536 39 S596 63 639 17'}" fill="none" stroke="#a78bd3" stroke-width="2.4"/></svg></div><div class="chart-days">${(monthly?['10/12','10/17','10/22','10/27','11/01','11/06','11/10']:['11/04','11/05','11/06','11/07','11/08','11/09','11/10']).map(d=>`<span>${d}</span>`).join('')}</div>`}
function renderNav(){document.getElementById('navigation').innerHTML=navGroups.map(g=>`<div class="nav-label">${g[0]}</div>${g[1].map(n=>`<button class="nav-item ${state.page===n[0]?'active':''}" data-nav="${n[0]}">${icon(n[1])}<span>${n[2]}</span>${n[3]?`<span class="count">${n[0]==='orders'?data.orders.length:n[0]==='forum'?data.posts.filter(p=>p.status==='待审核').length:data.orders.filter(o=>['进行中','已确认','已完成'].includes(o.status)).length}</span>`:''}</button>`).join('')}`).join('')}
function dashboard(){let pending=data.orders.filter(o=>o.paid==='待核验').length,unassigned=data.orders.filter(o=>o.owner==='待分配').length;return pageHead('早上好，知项管理员 <span class="spark">✧</span>','每一份认真，都值得被看见。今天也让项目稳步向前。',`<div class="date-picker">${icon('calendar')} 2026 年 11 月 10 日 · 周二</div>${btn('新建订单','new-order','plus','primary')}`,'A GOOD DAY TO MAKE THINGS HAPPEN')+`<div class="stats">${stat('本月订单收入','<small>¥</small>48,630','18.6%','money')}${stat('本月新增订单','32','12.5%','orders')}${stat('进行中的项目','18','4 个','delivery')}${stat('活跃用户','1,286','23.8%','users')}</div><div class="dashboard-columns"><section class="card"><div class="panel-head"><div><h2>业务增长，一目了然</h2><p>订单收入趋势 · 演示汇总数据</p></div><div class="segment"><button data-action="chart-period" data-id="近 7 天" class="${state.chartPeriod==='近 7 天'?'active':''}">近 7 天</button><button data-action="chart-period" data-id="近 30 天" class="${state.chartPeriod==='近 30 天'?'active':''}">近 30 天</button></div></div><div class="chart-summary"><div><small>累计收入</small><b>${state.chartPeriod==='近 7 天'?'¥ 18,260':'¥ 48,630'}</b></div><span>↗ 18.6%</span><div style="margin-left:auto;align-self:center" class="chart-legend"><span><i></i>本期收入</span><span><i class="gray"></i>上期收入</span></div></div>${chart()}</section><section class="card pending-card"><div class="panel-head"><div><h2>需要你的关注</h2><p>处理好当下，交付更从容</p></div><span class="pill purple">待办事项</span></div><div class="pending-list">${[['money','待核验收款','确认收款，项目即可推进',pending,'pending-pay'],['delivery','即将到期交付','未来 48 小时内需要交付',2,'delivery'],['users','待分配负责人','为每个项目找到合适的人',unassigned,'unassigned'],['chat','待审核内容','维护友善、有价值的社区',data.posts.filter(p=>p.status==='待审核').length,'forum']].map(x=>`<button class="pending-item" data-action="${x[4]}"><span>${icon(x[0])}</span><div><b>${x[1]}</b><small>${x[2]}</small></div><strong>${x[3]}</strong>${icon('chevron')}</button>`).join('')}</div></section></div><div class="quick-links">${[['orders','新建订单','让新项目，从这里开始','new-order'],['delivery','管理交付','跟进进度，交付有序','delivery'],['book','发布知识','把经验，变成共同成长','new-content'],['users','用户与会员','关注每一位用户的成长','users']].map(x=>`<button class="quick-link" data-action="${x[3]}"><span class="tile">${icon(x[0])}</span><div><b>${x[1]}</b><small>${x[2]}</small></div>${icon('arrow')}</button>`).join('')}</div><section class="card table-card"><div class="panel-head"><div><h2>最近订单 <span class="muted tiny" style="font-weight:400;margin-left:8px">从想法到交付，每一步都清晰</span></h2></div><button class="link" data-nav="orders">查看全部 ${icon('arrow')}</button></div>${orderTable(data.orders.slice(0,4),true)}</section>`}
function filteredOrders(){return data.orders.filter(o=>(state.status==='全部'||o.status===state.status)&&(!state.query||[o.title,o.id,o.user].join(' ').toLowerCase().includes(state.query.toLowerCase()))&&(state.payment==='全部收款状态'||o.paid===state.payment)&&(state.owner==='全部负责人'||o.owner===state.owner)).sort((a,b)=>state.sort==='金额从高到低'?b.amount-a.amount:state.sort==='金额从低到高'?a.amount-b.amount:state.sort==='最早创建'?a.date.localeCompare(b.date):b.date.localeCompare(a.date))}
function orderTable(list,compact=false){return `<div class="table-wrap"><table><thead><tr>${compact?'':`<th class="check-cell"><input type="checkbox" id="select-all" aria-label="全选当前页" ${list.length&&list.every(o=>state.selected.has(o.id))?'checked':''}></th>`}<th>订单信息</th><th>用户</th><th>订单金额</th><th>项目状态</th><th>收款状态</th>${compact?'':'<th>负责人</th>'}<th>操作</th></tr></thead><tbody>${list.map((o,i)=>`<tr>${compact?'':`<td class="check-cell"><input type="checkbox" data-select="${o.id}" aria-label="选择 ${esc(o.title)}" ${state.selected.has(o.id)?'checked':''}></td>`}<td><button class="cell-title" data-action="order-detail" data-id="${o.id}" style="padding:0;text-align:left">${esc(o.title)}</button><span class="cell-sub mono">${o.id} ${compact?'':' · '+o.date}</span></td><td><div class="table-user"><span class="avatar ${['purple','peach','blue','green'][i%4]}">${esc(o.user[0])}</span><span>${esc(o.user)}</span></div></td><td class="amount mono">${money(o.amount)}</td><td>${pill(o.status)}</td><td>${pill(o.paid)}</td>${compact?'':`<td>${o.owner==='待分配'?`<button class="link" data-action="assign" data-id="${o.id}">＋ 分配负责人</button>`:esc(o.owner)}</td>`}<td><div class="table-actions"><button data-action="order-detail" data-id="${o.id}">查看详情</button>${!compact?`<button class="icon-btn" data-action="edit-order" data-id="${o.id}" aria-label="编辑订单">${icon('edit')}</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>${!list.length?empty():''}`}
function orders(){let filtered=filteredOrders(),pages=Math.max(1,Math.ceil(filtered.length/6));state.pageNum=Math.min(state.pageNum,pages);let list=filtered.slice((state.pageNum-1)*6,state.pageNum*6);return pageHead('订单管理','把每一笔订单，变成可追踪的交付。',btn('导出演示数据','export-orders','download','secondary-mobile')+btn('新建订单','new-order','plus','primary'))+`<section class="card table-card"><div class="tabs">${['全部','草稿','已确认','进行中','已完成','已取消','已归档'].map(s=>`<button data-action="order-tab" data-id="${s}" class="${state.status===s?'active':''}">${s}<span>${s==='全部'?data.orders.length:data.orders.filter(o=>o.status===s).length}</span></button>`).join('')}</div><div class="filters"><label class="search-field">${icon('search')}<input id="order-search" placeholder="搜索订单名称、订单号或用户" value="${esc(state.query)}" aria-label="搜索订单"></label><select id="payment-filter" aria-label="收款状态">${['全部收款状态','已确认','待核验','未确认'].map(v=>`<option ${state.payment===v?'selected':''}>${v}</option>`).join('')}</select><select id="owner-filter" aria-label="负责人">${['全部负责人','陈老师','周老师','李老师','待分配'].map(v=>`<option ${state.owner===v?'selected':''}>${v}</option>`).join('')}</select><select id="sort-filter" aria-label="排序">${['最新创建','最早创建','金额从高到低','金额从低到高'].map(v=>`<option ${state.sort===v?'selected':''}>${v}</option>`).join('')}</select><button class="link" data-action="clear-filters">重置</button></div><div class="order-highlights"><span>筛选订单 <b>${filtered.length}</b></span><span>订单总额 <b>${money(filtered.reduce((a,o)=>a+o.amount,0))}</b></span><span>待核验收款 <b>${filtered.filter(o=>o.paid==='待核验').length} 笔</b></span></div>${state.selected.size?`<div class="bulkbar">已选择 ${state.selected.size} 个订单 <button class="link" data-action="clear-selection">取消选择</button>${btn('批量分配负责人','batch-assign','users','sm')}</div>`:''}${orderTable(list)}<div class="table-footer"><span>共 ${filtered.length} 条记录 · 每页 6 条 · 演示数据</span><div class="pagination"><span style="margin-right:8px">第 ${state.pageNum} / ${pages} 页</span><button data-action="page-prev" ${state.pageNum===1?'disabled':''} aria-label="上一页">‹</button>${Array.from({length:pages},(_,i)=>`<button data-action="page-num" data-id="${i+1}" class="${state.pageNum===i+1?'active':''}">${i+1}</button>`).join('')}<button data-action="page-next" ${state.pageNum===pages?'disabled':''} aria-label="下一页">›</button></div></div></section>`}
function delivery(){let list=data.orders.filter(o=>['进行中','已确认','已完成'].includes(o.status));return pageHead('项目交付','把进度看清楚，让每一次交付都有条不紊。',btn('交付规范','delivery-guide','book','secondary-mobile')+btn('新建交付','new-delivery','plus','primary'))+`<div class="insight-banner">${icon('sparkles')}<div><b>2 个项目即将到期，先把重要的事准备好</b><p>完善交付文件、检查运行环境，为用户留下一次顺畅的体验。</p></div>${btn('查看待交付','focus-delivery','','soft sm')}</div><div class="view-toolbar"><div class="row"><select id="delivery-owner" aria-label="筛选交付负责人">${['全部负责人','陈老师','周老师','李老师','待分配'].map(v=>`<option ${state.owner===v?'selected':''}>${v}</option>`).join('')}</select><span class="muted tiny">共 ${list.length} 个项目</span></div><div class="segment"><button data-action="delivery-view" data-id="board" class="${state.deliveryView==='board'?'active':''}">${icon('grid')} 看板</button><button data-action="delivery-view" data-id="list" class="${state.deliveryView==='list'?'active':''}">${icon('list')} 列表</button></div></div>${state.deliveryView==='board'?`<div class="kanban">${['待启动','开发中','待交付','已交付'].map(s=>{let items=list.filter(o=>o.stage===s&&(state.owner==='全部负责人'||o.owner===state.owner));return `<section class="lane" id="lane-${s}"><div class="lane-title"><i class="dot"></i>${s}<span>${items.length}</span></div>${items.map(o=>`<article class="project-card" tabindex="0" role="button" data-action="delivery-detail" data-id="${o.id}" aria-label="查看交付 ${esc(o.title)}"><small class="mono">${o.id}</small><h3>${esc(o.title)}</h3><p>${esc(o.user)} · ${o.type}</p>${pill(o.progress===100?'已完成':o.stage)}<div class="project-meta"><span>项目进度</span><span>${o.progress}%</span></div><div class="progress"><i style="width:${o.progress}%"></i></div><div class="project-bottom"><span class="row" style="gap:5px"><span class="avatar sm">${o.owner[0]}</span>${o.owner}</span><span class="due ${s==='待交付'?'urgent':''}">${icon('calendar')}${o.due.slice(5).replace('-','/')}</span></div></article>`).join('')}${items.length?'':`<div class="empty-lane">暂时没有${s}项目</div>`}</section>`}).join('')}</div>`:`<section class="card table-card"><div class="table-wrap"><table><thead><tr><th>项目</th><th>负责人</th><th>交付阶段</th><th>完成进度</th><th>预计交付</th><th>操作</th></tr></thead><tbody>${list.filter(o=>state.owner==='全部负责人'||o.owner===state.owner).map(o=>`<tr><td><b class="cell-title">${esc(o.title)}</b><span class="cell-sub">${o.user}</span></td><td>${o.owner}</td><td>${pill(o.stage)}</td><td><div class="row"><div class="progress" style="width:75px"><i style="width:${o.progress}%"></i></div>${o.progress}%</div></td><td>${o.due}</td><td><button class="link" data-action="delivery-detail" data-id="${o.id}">管理交付</button></td></tr>`).join('')}</tbody></table></div></section>`}`}
function knowledge(){let list=data.contents.filter(c=>(state.contentTab==='全部内容'||c.type===state.contentTab||c.status===state.contentTab)&&(!state.contentQuery||c.title.includes(state.contentQuery)));return pageHead('知识与素材','让好经验沉淀，让更多人少走一点弯路。',btn('新增内容','new-content','plus','primary'))+`<div class="view-toolbar"><div class="simple-tabs" style="margin:0">${['全部内容','知识文章','素材资源','草稿'].map(v=>`<button data-action="content-tab" data-id="${v}" class="${v===state.contentTab?'active':''}">${v}</button>`).join('')}</div><label class="search-field" style="min-width:230px;flex:0">${icon('search')}<input id="content-search" placeholder="搜索文章或素材" value="${esc(state.contentQuery)}"></label></div><div class="content-grid">${list.map(c=>`<article class="card content-card"><div class="content-cover ${c.cover}"><span class="cover-eyebrow">ZHIXIANG · ${c.type==='素材资源'?'TOOLKIT':'KNOWLEDGE'}</span><h3>${c.category}<br>让成长，有迹可循。</h3>${icon(c.icon)}</div><div class="content-body"><div class="between"><span class="pill purple">${c.category}</span>${pill(c.status)}</div><h3 style="margin-top:13px">${esc(c.title)}</h3><p>${esc(c.description)}</p><div class="content-meta"><span>${c.date}</span><span>${icon('eye')} ${c.views.toLocaleString()} 次浏览</span></div><div class="content-actions"><button class="link" data-action="edit-content" data-id="${c.id}">编辑内容</button><button class="link" data-action="toggle-content" data-id="${c.id}">${c.status==='已发布'?'移至草稿':'发布内容'} ${icon('arrow')}</button></div></div></article>`).join('')}</div>${list.length?'':empty()}`}
function users(){let list=data.users.filter(u=>(state.member==='全部会员'||u.member===state.member)&&(!state.userQuery||[u.name,u.id,u.email].join(' ').toLowerCase().includes(state.userQuery.toLowerCase())));return pageHead('用户与会员','了解每一位用户，陪伴每一步成长。',btn('导出演示用户','export-users','download','secondary-mobile'))+`<div class="stats">${stat('累计注册用户','2,418','16.8%','users')}${stat('Pro 会员','386','21.2%','sparkles')}${stat('本月新增用户','128','12.3%','plus')}${stat('会员续费率','76.2%','3.6%','refresh')}</div><section class="card table-card"><div class="filters"><label class="search-field">${icon('search')}<input id="user-search" placeholder="搜索用户昵称、ID 或邮箱" value="${esc(state.userQuery)}"></label><select id="member-filter" aria-label="会员类型">${['全部会员','Pro 会员','基础会员','免费用户'].map(v=>`<option ${state.member===v?'selected':''}>${v}</option>`).join('')}</select><span class="muted">共 ${list.length} 位示例用户</span></div><div class="table-wrap"><table><thead><tr><th>用户信息</th><th>会员等级</th><th>AI 可用额度</th><th>累计积分</th><th>注册时间</th><th>账户状态</th><th>操作</th></tr></thead><tbody>${list.map((u,i)=>`<tr><td><div class="table-user"><span class="avatar ${['purple','blue','peach','green'][i%4]}">${u.name[0]}</span><div><b class="cell-title">${u.name}</b><span class="cell-sub">${u.id} · ${u.email}</span></div></div></td><td>${pill(u.member)}</td><td class="mono">${u.quota.toLocaleString()} <span class="muted tiny">点</span></td><td class="mono">${u.points.toLocaleString()}</td><td class="muted small">${u.date}</td><td>${pill(u.status)}</td><td><button class="link" data-action="user-detail" data-id="${u.id}">管理用户</button></td></tr>`).join('')}</tbody></table></div>${list.length?'':empty()}<div class="table-footer"><span>共 ${list.length} 位用户 · 所有邮箱均为 example.com 演示地址</span><span>每页 12 条</span></div></section>`}
function forum(){let list=data.posts.filter(p=>state.forumTab==='全部内容'||p.status===state.forumTab);return pageHead('论坛管理','保护有价值的讨论，也让每一次表达被尊重。',btn('社区规范','community-guide','shield'))+`<div class="simple-tabs">${['待审核','已发布','已驳回','全部内容'].map(v=>`<button data-action="forum-tab" data-id="${v}" class="${state.forumTab===v?'active':''}">${v} ${v==='待审核'?`(${data.posts.filter(p=>p.status==='待审核').length})`:''}</button>`).join('')}</div>${list.map(p=>`<article class="card forum-card"><div class="between"><div class="table-user"><span class="avatar">${p.user[0]}</span><div><b class="cell-title">${p.user}</b><span class="cell-sub">今天 09:16 · ${p.tag}</span></div></div>${pill(p.status)}</div><h3>${p.pinned?'<span class="pill purple" style="margin-right:7px">置顶</span>':''}${esc(p.title)}</h3><p>${esc(p.text)}</p><div class="forum-foot"><span>${p.views} 次浏览 · ${p.comments} 条评论 · 演示内容</span><div class="row">${p.status==='待审核'?btn('驳回','reject-post','','sm',''+p.id)+btn('通过审核','approve-post','check','soft sm',''+p.id):p.status==='已发布'?btn(p.pinned?'取消置顶':'设为置顶','pin-post','','sm',''+p.id):btn('重新审核','review-post','','sm',''+p.id)}</div></div></article>`).join('')}${list.length?'':`<div class="card">${empty('当前没有'+state.forumTab+'的内容','内容状态会随你的演示操作更新。')}</div>`}`}
function analytics(){return pageHead('统计分析','把数据变成洞察，让每一个决定更有依据。',`<select id="analytics-period" aria-label="统计周期">${['本月','上月'].map(v=>`<option ${state.analyticsPeriod===v?'selected':''}>${v}</option>`).join('')}</select>${btn('下载报表','export-analytics','download')}`)+`<div class="demo-tip">${icon('chart')}统计页为独立的演示汇总数据，不代表订单示例列表的实时汇总。</div><div class="stats">${stat('订单收入',state.analyticsPeriod==='本月'?'<small>¥</small>48,630':'<small>¥</small>41,003','18.6%','money')}${stat('订单转化率',state.analyticsPeriod==='本月'?'8.6%':'7.4%','1.2%','chart')}${stat('平均交付周期','6.8 <small>天</small>','效率提升 12%','clock')}${stat('用户满意度','98.2%','2.1%','users')}</div><div class="dashboard-columns"><section class="card"><div class="panel-head"><div><h2>收入趋势</h2><p>本期订单收入与上期对比</p></div><span class="pill purple">${state.analyticsPeriod}</span></div><div class="chart-summary"><div><small>累计收入</small><b>${state.analyticsPeriod==='本月'?'¥ 48,630':'¥ 41,003'}</b></div><span>↗ 18.6%</span></div>${chart(state.analyticsPeriod)}</section><section class="card"><div class="panel-head"><div><h2>服务收入分布</h2><p>看见每一种服务的价值</p></div></div><div class="rank-list">${[['软件项目','¥ 36,472','75%'],['项目辅导','¥ 7,294','15%'],['设计服务','¥ 3,405','7%'],['会员服务','¥ 1,459','3%']].map((x,i)=>`<div class="rank-row"><span>0${i+1}</span><span>${x[0]}</span><strong>${x[1]}</strong><div class="progress"><i style="width:${x[2]}"></i></div></div>`).join('')}</div></section></div><section class="card"><div class="panel-head"><h2>交付质量概览</h2><span class="muted tiny">本月 · 演示汇总</span></div><div class="rank-list">${[['按时交付率','96.8%','96.8%'],['一次验收通过率','89.3%','89.3%'],['用户复购率','32.6%','32.6%']].map((x,i)=>`<div class="rank-row"><span>0${i+1}</span><span>${x[0]}</span><div class="progress" style="flex:1;max-width:60%;margin-left:auto"><i style="width:${x[2]}"></i></div><strong>${x[1]}</strong></div>`).join('')}</div></section>`}
function billing(){return pageHead('模型与计费','让 AI 能力清晰可控，让每一份用量都有依据。',btn('计费说明','billing-guide','book'))+`<div class="demo-tip">${icon('shield')}模型名称、单价和用量仅用于交互展示，不连接任何模型服务，不产生费用。</div><div class="stats">${stat('本月模拟调用','24,860','16.4%','sparkles')}${stat('Token 用量','18.6 <small>M</small>','12.8%','chart')}${stat('估算成本','<small>$</small>128.60','8.2%','money')}${stat('调用成功率','99.6%','0.3%','shield')}</div><section class="card table-card"><div class="panel-head"><div><h2>模型配置</h2><p>单价单位：美元 / 百万 Tokens · 全部为示例费率</p></div><span class="pill purple">${data.models.filter(m=>m.on).length} 个已启用</span></div><div class="table-wrap"><table><thead><tr><th>模型</th><th>输入单价</th><th>输出单价</th><th>调用策略</th><th>启用状态</th><th>操作</th></tr></thead><tbody>${data.models.map((m,i)=>`<tr><td><div class="table-user"><span class="avatar">${icon('sparkles')}</span><div><b class="cell-title">${m.name}</b><span class="cell-sub">${m.desc}</span></div></div></td><td>$ ${m.input.toFixed(2)}</td><td>$ ${m.output.toFixed(2)}</td><td><span class="pill gray">按 Token 计量</span></td><td><button class="switch ${m.on?'on':''}" role="switch" aria-checked="${m.on}" aria-label="启用 ${m.name}" data-action="model-toggle" data-id="${i}"><i></i></button></td><td><button class="link" data-action="model-edit" data-id="${i}">编辑费率</button></td></tr>`).join('')}</tbody></table></div></section><section class="card form-card" style="margin-top:20px"><h2>额度与使用规则</h2><p>为不同会员提供合适的 AI 使用额度</p>${[['免费用户','每月 10,000 点 · 基础模型'],['基础会员','每月 30,000 点 · 标准模型'],['Pro 会员','每月 100,000 点 · 全部模型']].map(x=>`<div class="setting-row"><div><b>${x[0]}</b><small>${x[1]}</small></div><button class="link" data-nav="users">管理会员额度 ${icon('arrow')}</button></div>`).join('')}</section>`}
function notifications(){let list=data.notices.filter(n=>state.noticeTab==='全部通知'||(state.noticeTab==='未读通知'&&!n.read)||n.type==='运营通知'&&state.noticeTab==='运营通知');return pageHead('通知中心','把重要的信息，送到恰当的人面前。',btn('全部标为已读','read-all','check','secondary-mobile')+btn('新建通知','new-notice','plus','primary'))+`<section class="card"><div class="tabs">${['全部通知','未读通知','运营通知'].map(v=>`<button data-action="notice-tab" data-id="${v}" class="${state.noticeTab===v?'active':''}">${v}${v==='未读通知'?`<span>${data.notices.filter(n=>!n.read).length}</span>`:''}</button>`).join('')}</div>${list.map(n=>`<article class="notice-item ${n.read?'read':''}"><span class="notice-icon">${icon(n.type==='运营通知'?'send':'bell')}</span><div><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><small>${n.time} · ${n.type}${n.audience?' · '+n.audience:''}</small></div><div class="right">${n.read?'<span class="muted tiny">已读</span>':`<span class="pill purple">未读</span><button class="link" data-action="read-notice" data-id="${n.id}">标为已读</button>`}</div></article>`).join('')}${list.length?'':empty('暂时没有通知','新的提醒会出现在这里。')}</section>`}
function settings(){let content=state.settingsTab==='站点信息'?`<h2>站点信息</h2><p>这些设置帮助用户认识知项，也塑造品牌的第一印象。</p><form id="settings-form"><div class="form-grid"><label class="field">站点名称<input name="site" value="${esc(data.settings.site)}" required maxlength="30"></label><label class="field">品牌标语<input name="slogan" value="${esc(data.settings.slogan)}" required maxlength="60"></label><label class="field full">联系邮箱<input name="email" type="email" value="${esc(data.settings.email)}" required><span class="hint">演示邮箱，不会向该地址发送邮件。</span></label><label class="field full">站点简介<textarea name="description">${esc(data.settings.description||'为学生提供项目实践、知识资源与 AI 辅助的一站式成长空间。')}</textarea></label></div><div class="form-footer"><button class="btn primary" type="submit">${icon('check')}保存演示配置</button></div></form>`:state.settingsTab==='权限与角色'?`<h2>权限与角色</h2><p>不同的工作职责，需要恰当的权限边界。</p>${[['超级管理员','全部模块与配置 · 1 位成员'],['项目负责人','订单查看、项目交付 · 3 位成员'],['内容运营','知识素材、通知、论坛审核 · 2 位成员']].map(x=>`<div class="setting-row"><div><b>${x[0]}</b><small>${x[1]}</small></div>${btn('查看权限','role-detail','shield','sm',x[0])}</div>`).join('')}<div class="read-note" style="margin-top:23px">当前为权限结构展示。原型不会创建账号或更改真实访问权限。</div>`:`<h2>运营偏好</h2><p>设置社区内容与业务提醒的默认行为。</p><div class="setting-row"><div><b>新内容发布前审核</b><small>社区新帖子进入审核队列后再发布</small></div><button class="switch ${data.settings.review?'on':''}" role="switch" aria-checked="${data.settings.review}" aria-label="新内容发布前审核" data-action="setting-toggle" data-id="review"><i></i></button></div><div class="setting-row"><div><b>交付到期提醒</b><small>预计交付前 48 小时生成站内提醒</small></div><button class="switch ${data.settings.notifications?'on':''}" role="switch" aria-checked="${data.settings.notifications}" aria-label="交付到期提醒" data-action="setting-toggle" data-id="notifications"><i></i></button></div><div class="read-note" style="margin-top:23px">设置仅保存在当前浏览器，不会启动真实提醒或后台任务。</div>`;return pageHead('基础配置','把日常运营的基础，打理得井井有条。')+`<div class="settings-layout"><aside class="card settings-nav">${['站点信息','权限与角色','运营偏好'].map(v=>`<button class="${state.settingsTab===v?'active':''}" data-action="settings-tab" data-id="${v}">${v}</button>`).join('')}</aside><section class="card form-card">${content}</section></div>`}
const renderers={dashboard,orders,delivery,knowledge,users,forum,analytics,billing,notifications,settings};
function render(preserveFocus=false){let el=document.activeElement,focusId=preserveFocus?el?.id:null,pos=el?.selectionStart;renderNav();document.getElementById('breadcrumb').textContent=names[state.page];document.getElementById('main').innerHTML=renderers[state.page]();hydrate();if(focusId){let input=document.getElementById(focusId);input?.focus();if(input?.setSelectionRange&&pos!==null)input.setSelectionRange(pos,pos)}}
function navigate(page){if(!names[page])page='dashboard';state.page=page;state.owner='全部负责人';document.body.classList.remove('menu-open');if(location.hash!=='#'+page)history.pushState({},'','#'+page);closeDialog(false);render();window.scrollTo(0,0)}
function toast(message){let el=document.createElement('div');el.className='toast';el.innerHTML=icon('check')+esc(message);document.getElementById('toasts').append(el);setTimeout(()=>el.remove(),3400)}
function openDialog(title,sub,body,footer='',modal=false){state.returnFocus=document.activeElement;let ov=document.getElementById('overlay'),d=document.getElementById('dialog');ov.hidden=false;ov.className='overlay'+(modal?' center':'');d.className=modal?'modal':'drawer';d.innerHTML=`<div class="dialog-head"><div><h2 id="dialog-title">${title}</h2><p>${sub}</p></div><button class="icon-btn" data-action="close" aria-label="关闭">${icon('close')}</button></div><div class="dialog-content">${body}</div>${footer?`<div class="dialog-footer">${footer}</div>`:''}`;document.body.style.overflow='hidden';setTimeout(()=>d.querySelector('input:not([type=hidden]),select,textarea,button')?.focus(),30)}
function closeDialog(restore=true){document.getElementById('overlay').hidden=true;document.body.style.overflow='';if(restore&&state.returnFocus?.isConnected)state.returnFocus.focus()}
function orderDetail(id){let o=data.orders.find(x=>x.id===id);if(!o)return;openDialog('订单详情','订单全流程，一处掌握。',`<div class="detail-title"><h3>${esc(o.title)}</h3>${pill(o.status)}</div><div class="detail-stats"><div><small>订单金额</small><b>${money(o.amount)}</b></div><div><small>收款状态</small><b style="font-size:16px">${o.paid}</b></div></div><div class="detail-section"><h3>基本信息</h3><div class="detail-grid">${[['订单编号',o.id],['创建日期',o.date],['关联用户',o.user],['服务类型',o.type],['项目负责人',o.owner],['预计交付',o.due]].map(x=>`<div><small>${x[0]}</small><span>${x[1]}</span></div>`).join('')}</div></div><div class="detail-section"><div class="between" style="margin-bottom:14px"><h3 style="margin:0">项目交付</h3><button class="link" data-action="delivery-detail" data-id="${id}">管理交付 ${icon('arrow')}</button></div><div class="between small" style="margin-bottom:10px"><span class="muted">${o.stage}</span><span>${o.progress}%</span></div><div class="progress"><i style="width:${o.progress}%"></i></div></div><div class="detail-section"><h3>活动记录</h3><div class="timeline">${o.lastEvent?`<div class="timeline-item"><b>${esc(o.lastEvent)}</b><p>刚刚 · 知项管理员 · 演示操作</p></div>`:''}<div class="timeline-item"><b>${o.status==='进行中'?'项目正在有序推进':'订单状态：'+o.status}</b><p>${o.date} 10:30 · ${o.owner}</p></div><div class="timeline-item"><b>创建订单</b><p>${o.date} 09:45 · 知项管理员</p></div></div></div><div class="read-note">所有操作仅更新演示数据，不会产生真实交易或通知。</div>`,btn('分配负责人','assign','users','',id)+btn('编辑订单','edit-order','edit','',id)+(o.paid!=='已确认'?btn('核验收款','verify-payment','check','primary',id):btn('管理交付','delivery-detail','delivery','primary',id)))}
function orderForm(id,deliveryOnly=false){let o=id?data.orders.find(x=>x.id===id):null;openDialog(o?'编辑订单':deliveryOnly?'新建交付项目':'新建订单','填写必要信息，开始一段有序的项目旅程。',`<form id="order-form"><input name="id" type="hidden" value="${o?.id||''}"><label class="field">项目名称<input name="title" value="${esc(o?.title||'')}" placeholder="例如：基于 Spring Boot 的校园服务平台" required maxlength="100"></label><div class="form-grid"><label class="field">关联用户<select name="uid">${data.users.map(u=>`<option value="${u.id}" ${o?.uid===u.id?'selected':''}>${u.name} · ${u.id}</option>`).join('')}</select></label><label class="field">服务类型<select name="type">${['软件项目','项目辅导','设计服务'].map(v=>`<option ${o?.type===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">订单金额（元）<input type="number" min="0" max="1000000" step="0.01" name="amount" value="${o?.amount??''}" required placeholder="0.00"></label><label class="field">预计交付日期<input type="date" name="due" value="${o?.due||'2026-11-20'}" required></label><label class="field">订单状态<select name="status">${['草稿','已确认','进行中','已完成','已取消','已归档'].map(v=>`<option ${(o?.status||(deliveryOnly?'已确认':'草稿'))===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">负责人<select name="owner">${['待分配','陈老师','周老师','李老师'].map(v=>`<option ${o?.owner===v?'selected':''}>${v}</option>`).join('')}</select></label></div><label class="field">订单备注<textarea name="note" placeholder="记录需求、交付要求或其他需要关注的事项">${esc(o?.note||'')}</textarea></label><div class="read-note">仅创建演示记录，不会发起收款、创建真实订单或联系用户。</div></form>`,btn('取消','close')+`<button type="submit" form="order-form" class="btn primary">${icon('check')}${o?'保存修改':'创建演示订单'}</button>`)}
function assign(id){let ids=id?[id]:[...state.selected];openDialog('分配负责人',`为 ${ids.length} 个订单指定项目负责人。`,`<form id="assign-form"><input type="hidden" name="ids" value="${ids.join(',')}"><label class="field">项目负责人<select name="owner">${['陈老师','周老师','李老师'].map(v=>`<option>${v}</option>`).join('')}</select></label><div class="read-note">负责人可以在交付管理中查看项目进度。此操作仅为演示，不会发送通知。</div></form>`,btn('取消','close')+`<button type="submit" form="assign-form" class="btn primary">确认分配</button>`,true)}
function deliveryDetail(id){let o=data.orders.find(x=>x.id===id);if(!o)return;openDialog('项目交付','用清晰的版本和文件，完成更好的交付。',`<div class="detail-title"><h3>${esc(o.title)}</h3>${pill(o.stage)}</div><div class="detail-grid" style="margin-bottom:24px"><div><small>负责人</small><span>${o.owner}</span></div><div><small>预计交付</small><span>${o.due}</span></div></div><form id="delivery-form"><input type="hidden" name="id" value="${id}"><div class="form-grid"><label class="field">交付阶段<select name="stage">${['待启动','开发中','待交付','已交付'].map(v=>`<option ${o.stage===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">完成进度（%）<input type="number" name="progress" min="0" max="100" step="1" value="${o.progress}" required></label></div></form><div class="detail-section"><div class="between"><h3>交付文件 · v1.0</h3><span class="pill purple">演示文件</span></div>${[['ZIP','项目源代码.zip','包含前后端代码与配置'],['DOC','部署说明.md','运行环境与启动步骤'],['PDF','功能验收清单.txt','功能点与检查标准']].map(x=>`<div class="file-row"><span class="file-type">${x[0]}</span><div><b>${x[1]}</b><small>${x[2]}</small></div><button class="link" data-action="preview-file" data-id="${x[1]}">预览</button></div>`).join('')}</div><div class="detail-section"><h3>交付检查</h3>${['项目可在说明环境运行','代码与文档已整理','关键功能已完成验收'].map((x,i)=>`<label class="setting-row" style="padding:9px 0;font-size:11px"><span>${x}</span><input type="checkbox" name="check${i}" form="delivery-form" ${(o.checks?o.checks[i]:o.progress>=90)?'checked':''}></label>`).join('')}</div><div class="read-note">示例交付文件仅展示目录与结构，不包含真实项目源码。保存会更新看板。</div>`,btn('关闭','close')+`<button type="submit" form="delivery-form" class="btn primary">${icon('check')}保存交付进度</button>`)}
function userDetail(id){let u=data.users.find(x=>x.id===id);openDialog('用户管理','查看用户信息与会员权益。',`<div class="row" style="margin-bottom:25px"><span class="avatar" style="width:50px;height:50px;font-size:20px">${u.name[0]}</span><div><h2>${u.name}</h2><p class="muted small">${u.id} · ${u.email}</p></div></div><form id="user-form"><input type="hidden" name="id" value="${id}"><div class="form-grid"><label class="field">会员等级<select name="member">${['免费用户','基础会员','Pro 会员'].map(v=>`<option ${u.member===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">账户状态<select name="status">${['正常','已停用'].map(v=>`<option ${u.status===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">AI 可用额度（点）<input type="number" min="0" step="1" max="10000000" required name="quota" value="${u.quota}"></label><label class="field">累计积分<input type="number" min="0" step="1" max="10000000" required name="points" value="${u.points}"></label></div></form><div class="detail-section"><h3>关联订单</h3>${data.orders.filter(o=>o.uid===id).map(o=>`<div class="file-row"><span class="file-type">${icon('orders')}</span><div><b>${esc(o.title)}</b><small>${o.id}</small></div><button class="link" data-action="order-detail" data-id="${o.id}">查看</button></div>`).join('')||'<p class="muted small">暂无订单</p>'}</div><div class="read-note">会员、额度与停用状态仅在此原型内生效，不修改真实用户信息。</div>`,btn('取消','close')+`<button type="submit" form="user-form" class="btn primary">保存用户信息</button>`)}
function contentForm(id){let c=data.contents.find(x=>x.id===Number(id));openDialog(c?'编辑内容':'新增内容','把值得分享的知识，整理成清晰的内容。',`<form id="content-form"><input type="hidden" name="id" value="${c?.id||''}"><label class="field">内容标题<input name="title" maxlength="100" required value="${esc(c?.title||'')}" placeholder="输入一个清晰、有吸引力的标题"></label><div class="form-grid"><label class="field">内容类型<select name="type">${['知识文章','素材资源'].map(v=>`<option ${c?.type===v?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">分类<select name="category">${['项目指南','文档写作','开发实践','模板工具','答辩准备','AI 效率'].map(v=>`<option ${c?.category===v?'selected':''}>${v}</option>`).join('')}</select></label></div><label class="field">内容简介<textarea name="description" required maxlength="500">${esc(c?.description||'')}</textarea></label><label class="field">正文 / 资源说明<textarea name="body" style="min-height:180px" placeholder="写下内容正文，或说明素材的用途与使用方法。">${esc(c?.body||'')}</textarea></label><label class="field">发布状态<select name="status"><option ${c?.status==='草稿'?'selected':''}>草稿</option><option ${c?.status==='已发布'?'selected':''}>已发布</option></select></label><div class="read-note">原型保存到本浏览器，不会同步到学生端或真实内容库。</div></form>`,btn('取消','close')+`<button type="submit" form="content-form" class="btn primary">保存内容</button>`)}
function newNotice(){openDialog('新建通知','先确认内容与接收范围，再完成演示发送。',`<form id="notice-form"><label class="field">通知标题<input name="title" required maxlength="80" placeholder="例如：本周项目交付安排"></label><label class="field">接收范围<select name="audience"><option>全部用户</option><option>Pro 会员</option><option>项目负责人</option></select></label><label class="field">通知内容<textarea name="body" required maxlength="1000" placeholder="填写清晰、简洁的通知内容。" style="min-height:140px"></textarea></label><div class="read-note">此处为演示发送。不会实际发送邮件、短信或站内消息。</div></form>`,btn('取消','close')+`<button type="submit" form="notice-form" class="btn primary">预览通知</button>`,true)}
function showSearch(q=''){let matches=q?[...Object.entries(names).filter(([,v])=>v.includes(q)).map(([k,v])=>({title:v,type:'功能',nav:k})),...data.orders.filter(o=>o.title.includes(q)||o.id.toLowerCase().includes(q.toLowerCase())).slice(0,5).map(o=>({title:o.title,type:'订单',id:o.id})),...data.users.filter(u=>u.name.includes(q)||u.id.toLowerCase().includes(q.toLowerCase())).slice(0,3).map(u=>({title:u.name,type:'用户',user:u.id}))]:[{title:'订单管理',type:'常用功能',nav:'orders'},{title:'项目交付',type:'常用功能',nav:'delivery'},{title:'用户与会员',type:'常用功能',nav:'users'}];let html=matches.map(x=>`<button ${x.nav?`data-nav="${x.nav}"`:x.user?`data-action="user-detail" data-id="${x.user}"`:`data-action="order-detail" data-id="${x.id}"`}>${icon(x.nav?'grid':x.user?'users':'orders')}<span>${esc(x.title)}</span><small>${x.type}</small></button>`).join('')||empty('没有找到结果','换个关键词再试试。');if(document.getElementById('global-search-input'))document.getElementById('search-results').innerHTML=html;else openDialog('快速搜索','搜索演示订单、用户或功能入口。',`<label class="search-field">${icon('search')}<input id="global-search-input" placeholder="试试搜索「校园」或「林同学」" autocomplete="off"></label><div class="search-results" id="search-results">${html}</div>`,'',true)}
function download(name,rows){let csv='\ufeff'+rows.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('演示数据已导出')}
function guide(title,body){openDialog(title,'知项管理后台 · 演示说明',body,btn('知道了','close','','primary'),true)}
let noticeDraft=null;
document.addEventListener('click',e=>{let nav=e.target.closest('[data-nav]');if(nav){navigate(nav.dataset.nav);return}let b=e.target.closest('[data-action]');if(!b)return;let a=b.dataset.action,id=b.dataset.id,o=data.orders.find(x=>x.id===id);switch(a){case'menu':document.body.classList.toggle('menu-open');break;case'close':closeDialog();break;case'search':showSearch();break;case'profile':guide('知项管理员',`<div class="row" style="margin-bottom:20px"><span class="avatar">管</span><div><b>超级管理员</b><p class="muted small">当前为独立演示工作区</p></div></div><div class="read-note">可以体验各模块的管理流程。没有真实登录账号，所有修改仅保存在本浏览器。</div>`);break;case'notifications':case'delivery':case'users':case'forum':navigate(a);break;case'pending-pay':state.payment='待核验';state.status='全部';navigate('orders');break;case'unassigned':navigate('orders');state.owner='待分配';render();break;case'new-order':orderForm();break;case'new-delivery':orderForm(null,true);break;case'edit-order':orderForm(id);break;case'order-detail':orderDetail(id);break;case'assign':assign(id);break;case'batch-assign':assign();break;case'verify-payment':openDialog('核验收款','请核对本条演示订单的收款信息。',`<div class="detail-title"><h3>${esc(o.title)}</h3></div><div class="detail-stats"><div><small>订单金额</small><b>${money(o.amount)}</b></div><div><small>当前状态</small><b style="font-size:16px">${o.paid}</b></div></div><div class="read-note">确认后，将本条演示订单标记为已收款。本操作不会进行任何资金交易。</div>`,btn('取消','close')+btn('确认已收款','confirm-payment','check','primary',id),true);break;case'confirm-payment':o.paid='已确认';o.lastEvent='核验收款完成';persist();render();orderDetail(id);toast('已核验演示收款');break;case'order-tab':state.status=id;state.pageNum=1;state.selected.clear();render();break;case'clear-filters':Object.assign(state,{query:'',payment:'全部收款状态',owner:'全部负责人',sort:'最新创建',pageNum:1});render();break;case'clear-selection':state.selected.clear();render();break;case'page-prev':state.pageNum--;render();break;case'page-next':state.pageNum++;render();break;case'page-num':state.pageNum=Number(id);render();break;case'chart-period':state.chartPeriod=id;render();break;case'delivery-view':state.deliveryView=id;render();break;case'focus-delivery':state.deliveryView='board';render();document.getElementById('lane-待交付')?.scrollIntoView({behavior:'smooth',block:'center'});break;case'delivery-detail':deliveryDetail(id);break;case'preview-file':guide('文件预览',`<h3 style="margin-bottom:16px">${esc(id)}</h3><div class="read-note">${id.endsWith('.zip')?'项目源代码目录（演示）<br><br>frontend/ · 用户界面<br>backend/ · 接口与服务<br>database/ · 数据库脚本<br>README.md · 启动说明':id.endsWith('.md')?'部署说明（演示）<br><br>1. 准备 Node.js 与 Java 运行环境。<br>2. 按说明配置数据库连接。<br>3. 安装依赖并启动前后端服务。<br>4. 使用测试账号检查主要功能。':'功能验收清单（演示）<br><br>✓ 用户登录与权限<br>✓ 核心业务流程<br>✓ 数据展示与查询<br>✓ 异常提示与页面适配'}</div>`);break;case'user-detail':userDetail(id);break;case'new-content':contentForm();break;case'edit-content':contentForm(id);break;case'content-tab':state.contentTab=id;render();break;case'toggle-content':{let c=data.contents.find(x=>x.id===Number(id));c.status=c.status==='已发布'?'草稿':'已发布';persist();render();toast('内容已'+(c.status==='已发布'?'发布到演示库':'移至演示草稿'));break}case'forum-tab':state.forumTab=id;render();break;case'approve-post':case'review-post':case'pin-post':{let p=data.posts.find(x=>x.id===Number(id));if(a==='pin-post')p.pinned=!p.pinned;else p.status=a==='approve-post'?'已发布':'待审核';persist();render();toast(a==='pin-post'?'已更新演示置顶状态':'已更新演示审核状态');break}case'reject-post':openDialog('驳回内容','说明原因，帮助用户完善内容。',`<form id="reject-form"><input type="hidden" name="id" value="${id}"><label class="field">驳回原因<select name="reason"><option>内容与社区主题无关</option><option>包含广告或推广</option><option>需要补充说明</option><option>不符合社区规范</option></select></label><label class="field">补充说明<textarea name="note" placeholder="可填写具体建议"></textarea></label></form>`,btn('取消','close')+`<button type="submit" form="reject-form" class="btn primary">确认驳回（演示）</button>`,true);break;case'model-toggle':data.models[Number(id)].on=!data.models[Number(id)].on;persist();render();toast('已更新模型演示状态');break;case'model-edit':{let m=data.models[Number(id)];openDialog('编辑模型费率',m.name+' · 示例费率，不产生真实费用',`<form id="model-form"><input type="hidden" name="id" value="${id}"><label class="field">输入单价（美元 / 百万 Tokens）<input name="input" type="number" min="0" max="1000" step="0.01" required value="${m.input}"></label><label class="field">输出单价（美元 / 百万 Tokens）<input name="output" type="number" min="0" max="1000" step="0.01" required value="${m.output}"></label></form>`,btn('取消','close')+`<button type="submit" form="model-form" class="btn primary">保存演示费率</button>`,true);break}case'notice-tab':state.noticeTab=id;render();break;case'read-notice':data.notices.find(n=>n.id===Number(id)).read=true;persist();render();break;case'read-all':data.notices.forEach(n=>n.read=true);persist();render();toast('全部通知已标为已读');break;case'new-notice':newNotice();break;case'publish-notice':if(noticeDraft){data.notices.unshift({...noticeDraft,id:Date.now(),type:'运营通知',time:'刚刚',read:true});noticeDraft=null;persist();closeDialog();navigate('notifications');toast('通知已模拟发送，不会实际触达用户')}break;case'settings-tab':state.settingsTab=id;render();break;case'setting-toggle':data.settings[id]=!data.settings[id];persist();render();toast('演示偏好已保存');break;case'role-detail':guide(id+'权限',`<div class="read-note">${id==='超级管理员'?'可访问全部业务与系统模块。':id==='项目负责人'?'订单：查看相关订单<br>交付：更新进度、整理交付文件<br>用户：查看项目关联用户':'内容：创建和编辑知识、素材<br>论坛：审核与置顶帖子<br>通知：编辑运营通知'}</div>`);break;case'delivery-guide':guide('交付规范',`<div class="read-note">1. 确认项目需求、负责人和交付日期。<br><br>2. 按开发中 → 待交付 → 已交付更新阶段。<br><br>3. 准备源代码、部署文档和验收清单。<br><br>4. 检查运行环境与关键功能后完成交付。</div>`);break;case'community-guide':guide('社区规范',`<div class="read-note">友善交流，尊重每一种认真表达。<br><br>鼓励分享项目经验、学习资源和具体问题。<br><br>尊重原创，不发布侵权内容、无关广告或他人隐私。<br><br>审核有据可循，驳回时说明具体原因。</div>`);break;case'billing-guide':guide('计费说明',`<div class="read-note">本页所有模型、单价与用量均为演示。<br><br>示例成本 = 输入 Tokens ÷ 1,000,000 × 输入单价 + 输出 Tokens ÷ 1,000,000 × 输出单价。<br><br>会员点数用于展示额度管理流程，不代表实际货币或真实 Token 兑换规则。</div>`);break;case'export-orders':download('知项订单-演示数据.csv',[['订单号','项目名称','用户','金额','状态','收款','负责人','日期'],...filteredOrders().map(o=>[o.id,o.title,o.user,o.amount,o.status,o.paid,o.owner,o.date])]);break;case'export-users':download('知项用户-演示数据.csv',[['ID','昵称','邮箱','会员','额度','状态'],...data.users.map(u=>[u.id,u.name,u.email,u.member,u.quota,u.status])]);break;case'export-analytics':download('知项统计-演示数据.csv',[['指标','本月','说明'],['订单收入',48630,'演示汇总数据'],['订单转化率','8.6%','演示汇总数据'],['平均交付周期','6.8 天','演示汇总数据'],['用户满意度','98.2%','演示汇总数据']]);break;case'reset':openDialog('重置演示数据','恢复到原型的初始状态。',`<p class="muted small">将清除本浏览器中新增的演示订单、内容与配置修改，不影响任何真实业务数据。</p>`,btn('取消','close')+btn('确认重置','confirm-reset','refresh','primary'),true);break;case'confirm-reset':data=structuredClone(initial);persist();state.selected.clear();closeDialog();render();toast('已恢复初始演示数据');break;}});
document.addEventListener('input',e=>{const map={'order-search':'query','content-search':'contentQuery','user-search':'userQuery'};if(map[e.target.id]){state[map[e.target.id]]=e.target.value;state.pageNum=1;render(true)}if(e.target.id==='global-search-input')showSearch(e.target.value)});
document.addEventListener('change',e=>{let t=e.target,map={'payment-filter':'payment','owner-filter':'owner','sort-filter':'sort','delivery-owner':'owner','member-filter':'member','analytics-period':'analyticsPeriod'};if(map[t.id]){state[map[t.id]]=t.value;state.pageNum=1;render()}if(t.dataset.select){t.checked?state.selected.add(t.dataset.select):state.selected.delete(t.dataset.select);render()}if(t.id==='select-all'){let list=filteredOrders().slice((state.pageNum-1)*6,state.pageNum*6);list.forEach(o=>t.checked?state.selected.add(o.id):state.selected.delete(o.id));render()}});
document.addEventListener('submit',e=>{e.preventDefault();let form=e.target;if(!form.reportValidity())return;let f=Object.fromEntries(new FormData(form));switch(form.getAttribute('id')){case'order-form':{let u=data.users.find(u=>u.id===f.uid),existing=data.orders.find(o=>o.id===f.id);if(existing){Object.assign(existing,f,{amount:Number(f.amount),user:u.name,lastEvent:'更新订单信息'});if(f.status==='已完成'){existing.stage='已交付';existing.progress=100}}else{let id='ZX20261110'+String(Date.now()).slice(-5);data.orders.unshift({...f,id,amount:Number(f.amount),user:u.name,paid:'未确认',date:'2026-11-10',stage:f.status==='进行中'?'开发中':f.status==='已完成'?'已交付':'待启动',progress:f.status==='已完成'?100:0,lastEvent:'创建演示订单'})}persist();closeDialog();Object.assign(state,{query:'',status:'全部',payment:'全部收款状态',pageNum:1});navigate('orders');toast(existing?'演示订单已更新':'演示订单已创建');break}case'assign-form':f.ids.split(',').forEach(id=>{let o=data.orders.find(o=>o.id===id);if(o){o.owner=f.owner;o.lastEvent='分配负责人：'+f.owner}});state.selected.clear();persist();closeDialog();render();toast('演示负责人已分配');break;case'delivery-form':{let o=data.orders.find(o=>o.id===f.id);let checks=[0,1,2].map(i=>f['check'+i]==='on');if(f.stage==='已交付'&&!checks.every(Boolean)){toast('完成交付前，请先勾选全部交付检查项');return}o.stage=f.stage;o.progress=f.stage==='已交付'?100:Number(f.progress);o.checks=checks;if(f.stage==='已交付')o.status='已完成';else if(f.stage==='开发中'||f.stage==='待交付')o.status='进行中';else o.status='已确认';o.lastEvent='更新交付阶段：'+f.stage;persist();closeDialog();render();toast('交付进度已保存');break}case'user-form':{let u=data.users.find(u=>u.id===f.id);Object.assign(u,f,{quota:Number(f.quota),points:Number(f.points)});persist();closeDialog();render();toast('演示用户信息已保存');break}case'content-form':{let c=data.contents.find(c=>c.id===Number(f.id));if(c)Object.assign(c,f,{id:c.id});else data.contents.unshift({...f,id:Date.now(),views:0,date:'2026-11-10',cover:'purple',icon:'book'});persist();closeDialog();navigate('knowledge');toast('内容已保存到演示库');break}case'reject-form':{let p=data.posts.find(p=>p.id===Number(f.id));p.status='已驳回';p.reason=f.reason;p.note=f.note;persist();closeDialog();render();toast('演示内容已驳回');break}case'model-form':Object.assign(data.models[Number(f.id)],{input:Number(f.input),output:Number(f.output)});persist();closeDialog();render();toast('演示费率已保存');break;case'notice-form':noticeDraft=f;openDialog('确认通知预览','模拟发送，不会联系真实用户。',`<span class="pill purple">${esc(f.audience)}</span><h3 style="font-size:16px;margin:17px 0">${esc(f.title)}</h3><p style="font-size:12px;line-height:2;color:#9f86af;white-space:pre-wrap">${esc(f.body)}</p><div class="read-note" style="margin-top:20px">发送后，演示通知会出现在通知中心。</div>`,btn('取消','close')+btn('确认模拟发送','publish-notice','send','primary'),true);break;case'settings-form':Object.assign(data.settings,f);persist();toast('演示配置已保存');break;}});
document.getElementById('overlay').addEventListener('click',e=>{if(e.target.id==='overlay')closeDialog()});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();showSearch()}if(e.key==='Escape'){closeDialog();document.body.classList.remove('menu-open')}if(e.key==='Enter'&&e.target.matches('.project-card'))e.target.click();if(e.key==='Tab'&&!document.getElementById('overlay').hidden){let controls=[...document.getElementById('dialog').querySelectorAll('button:not([disabled]),input:not([type=hidden]),select,textarea,a[href]')].filter(x=>x.getClientRects().length);if(!controls.length)return;let first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
window.addEventListener('popstate',()=>navigate(location.hash.slice(1)));window.addEventListener('hashchange',()=>{if(state.page!==location.hash.slice(1))navigate(location.hash.slice(1))});state.page=names[location.hash.slice(1)]?location.hash.slice(1):'dashboard';render();hydrate();
